\mathrm{df\text{-}uniform\text{-}continuity\text{-}modulus}\vdash\;\begin{aligned}
\mathsf{Unif}_{\mathcal A,\mathcal B}(\Phi)&\leftrightarrow\mathsf{TotalCont}_{\mathcal A,\mathcal B}(\Phi)\land\forall k\exists m\forall x,x',y,y'\\
&\quad[(\mathsf{Val}_{\mathcal A,\mathcal B}(\Phi,x,y)\land\mathsf{Val}_{\mathcal A,\mathcal B}(\Phi,x',y')\land\delta_{\mathcal A}(x,x')<_R\widehat{\varepsilon_m})\to\delta_{\mathcal B}(y,y')<_R\widehat{\varepsilon_k}],\\
\mathsf{Mod}_{\mathcal A,\mathcal B}(\Phi,h)&\leftrightarrow\mathsf{TotalCont}_{\mathcal A,\mathcal B}(\Phi)\land\mathsf{Fun}(h,N,N)\land\forall k\forall x,x',y,y'\\
&\quad[(\mathsf{Val}_{\mathcal A,\mathcal B}(\Phi,x,y)\land\mathsf{Val}_{\mathcal A,\mathcal B}(\Phi,x',y')\land\delta_{\mathcal A}(x,x')<_R\widehat{\varepsilon_{h(k)}})\to\delta_{\mathcal B}(y,y')<_R\widehat{\varepsilon_k}].
\end{aligned}
